// Package blob stores uploaded file bytes. The local driver is the only
// implementation; an OSS/S3 driver can satisfy app.FileBlobStore later
// without touching use cases or handlers.
package blob

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/imajinyun/gofly/examples/gosky/internal/app"
)

const folderMode os.FileMode = 0o750

// LocalStore writes uploads beneath Root as <root>/<tenant>/<folder>/<key>.
// Every path component except Root is derived from validated integers or a
// storage key generated by the caller; client file names never touch disk.
type LocalStore struct {
	root string
}

func NewLocalStore(root string) (*LocalStore, error) {
	root = strings.TrimSpace(root)
	if root == "" {
		return nil, fmt.Errorf("blob root is required")
	}
	absolute, err := filepath.Abs(root)
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(absolute, 0o750); err != nil {
		return nil, err
	}
	return &LocalStore{root: absolute}, nil
}

// Root returns the absolute on-disk root.
func (s *LocalStore) Root() string { return s.root }

func (s *LocalStore) dir(tenantID uint64, folderType uint8) (string, error) {
	if tenantID == 0 || folderType == 0 || folderType > 4 {
		return "", fmt.Errorf("invalid blob location tenant=%d folder=%d", tenantID, folderType)
	}
	dir := filepath.Join(s.root, strconv.FormatUint(tenantID, 10), strconv.FormatUint(uint64(folderType), 10))
	clean := filepath.Clean(dir)
	// Defense in depth: the joined directory must remain under root.
	if !isWithin(clean, s.root) {
		return "", fmt.Errorf("blob path escapes storage root")
	}
	return clean, nil
}

func (s *LocalStore) keyPath(tenantID uint64, folderType uint8, key string) (string, error) {
	key = strings.TrimSpace(key)
	if !validKey(key) {
		return "", fmt.Errorf("invalid storage key")
	}
	dir, err := s.dir(tenantID, folderType)
	if err != nil {
		return "", err
	}
	target := filepath.Clean(filepath.Join(dir, key))
	if !isWithin(target, dir) {
		return "", fmt.Errorf("storage key escapes folder")
	}
	return target, nil
}

// Put creates the folder and streams content to a temp file before an atomic
// rename, so a failed upload never leaves a partially written key readable.
func (s *LocalStore) Put(ctx context.Context, tenantID uint64, folderType uint8, key, _ string, content io.Reader, declared int64) error {
	target, err := s.keyPath(tenantID, folderType, key)
	if err != nil {
		return err
	}
	dir := filepath.Dir(target)
	if err := os.MkdirAll(dir, folderMode); err != nil {
		return fmt.Errorf("create blob dir: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".upload-*")
	if err != nil {
		return fmt.Errorf("create temp blob: %w", err)
	}
	tmpName := tmp.Name()
	defer func() { _ = os.Remove(tmpName) }()

	written, err := io.Copy(tmp, io.LimitReader(content, declared+1))
	if err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write blob: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close blob: %w", err)
	}
	if written != declared {
		return fmt.Errorf("blob size mismatch: declared=%d written=%d", declared, written)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := os.Chmod(tmpName, 0o640); err != nil {
		return fmt.Errorf("chmod blob: %w", err)
	}
	if err := os.Rename(tmpName, target); err != nil {
		return fmt.Errorf("finalize blob: %w", err)
	}
	return nil
}

func (s *LocalStore) Open(_ context.Context, tenantID uint64, folderType uint8, key string) (io.ReadCloser, app.FileRecord, error) {
	target, err := s.keyPath(tenantID, folderType, key)
	if err != nil {
		return nil, app.FileRecord{}, err
	}
	file, err := os.Open(target)
	if err != nil {
		return nil, app.FileRecord{}, err
	}
	info, err := file.Stat()
	if err != nil {
		_ = file.Close()
		return nil, app.FileRecord{}, err
	}
	return file, app.FileRecord{FileSize: info.Size()}, nil
}

// validKey accepts only uuid-like keys optionally followed by one safe
// extension segment, e.g. 3f2c...0a.png.
func validKey(key string) bool {
	if key == "" || len(key) > 128 || strings.ContainsAny(key, "/\\\x00") {
		return false
	}
	for _, r := range key {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '_', r == '.':
		default:
			return false
		}
	}
	return !strings.HasPrefix(key, ".") && !strings.HasSuffix(key, ".")
}

func isWithin(path, base string) bool {
	relative, err := filepath.Rel(base, path)
	if err != nil {
		return false
	}
	return relative != ".." && !strings.HasPrefix(relative, ".."+string(os.PathSeparator))
}
